<!doctype html><html lang="id"><head><meta charset="UTF-8"><title>KIR</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container mt-4"><h1 class="h3">Kartu Inventaris Ruangan</h1><p>Ruangan: <?= esc($aset[0]['ruangan_nama'] ?? '-') ?></p><table class="table table-bordered"><thead><tr><th>No</th><th>Registrasi</th><th>Nama Aset</th><th>KIB</th><th>Penanggung Jawab</th><th>Tahun</th><th>Kondisi</th></tr></thead><tbody><?php foreach ($aset as $i => $row): ?><tr><td><?= $i + 1 ?></td><td><?= esc($row['nomor_registrasi']) ?></td><td><?= esc($row['nama_aset']) ?></td><td><?= esc($row['kategori_kib']) ?></td><td><?= esc($row['penanggung_jawab'] ?? 'Belum ditentukan') ?></td><td><?= esc($row['tahun_perolehan']) ?></td><td><?= esc($row['kondisi']) ?></td></tr><?php endforeach ?></tbody></table><button class="btn btn-primary" onclick="window.print()">Cetak</button></main></body></html>
